## Code Example

```javascript
function sortHybrid(a){
  const TH = 16;
  const swap=(i,j)=>{ [a[i],a[j]]=[a[j],a[i]]; };
  const insertSort=(l,r)=>{
    for(let i=l+1;i<=r;i++){
      let x=a[i], j=i-1;
      while(j>=l && a[j]>x){ a[j+1]=a[j]; j--; }
      a[j+1]=x;
    }
  };
  const partition=(lo,hi)=>{
    const p=a[lo+((hi-lo)>>1)];
    let i=lo, lt=lo, gt=hi;
    while(i<=gt){
      if(a[i]<p){ swap(i,lt); i++; lt++; }
      else if(a[i]>p){ swap(i,gt); gt--; }
      else i++;
    }
    return [lt,gt];
  };
  const qs=(lo,hi)=>{
    if(lo>=hi) return;
    if(hi-lo+1 <= TH){ insertSort(lo,hi); return; }
    const [l,r] = partition(lo,hi);
    qs(lo, l-1);
    qs(r+1, hi);
  };
  qs(0,a.length-1);
}
```

